{
  "qid": "0017-L3-01",
  "sample_id": "0017",
  "gen_prompt": "描绘返回舱串联躯干段构型的龙飞船在地球上空执行与国际空间站对接前最后接近的瞬间。采用写实航天摄影风格和三分之四侧视中近景，龙飞船完整无遮挡，位于画面左下方并沿右上方向接近目标；国际空间站仅露出局部结构。背景呈现地球弧面与晨昏交界，冷蓝色边缘光勾勒主体，画面中不出现喷焰。",
  "invocation": "L3",
  "knowledge_dim": "载人航天器构型、在轨对接状态与外部结构知识",
  "fidelity_checks": [
    {
      "check": "主体必须明确属于工程制造的载人航天器，而不是以名称作字面联想得到的生物或幻想角色。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "1"
        ],
        "derivation_chain": "题面点名龙飞船并要求执行载人航天任务→约束[1]规定该概念属于载人太空飞行器→视觉结论为主体应呈现可辨认的工程航天器类别。"
      },
      "rubric": {
        "tier_0": "主体缺失，或被画成动物、幻想角色、普通飞机、汽车等其他类别，而没有可辨认的载人航天器主体。",
        "tier_1": "主体清楚呈现为工程制造的载人航天器，类别判读明确。",
        "tier_2": "在满足Pass的基础上，工程结构分区、接缝和设备细节刻画精确，使载人航天器属性在复杂背景中仍高度明确。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "题面要求主体完整无遮挡；若主体过小、严重裁切或模糊到无法判断类别，本条按Fail处理。"
    },
    {
      "check": "前部载人舱应呈窄端在顶、宽大钝圆端在后的钝头锥形或钟形胶囊轮廓，不得呈球体、细长箭体、平板平台或单纯圆柱舱段。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "2"
        ],
        "derivation_chain": "题面要求完整展示龙飞船→约束[2]限定其载人返回部分的固有几何形态→视觉结论为前部必须出现窄顶宽底的钝头胶囊轮廓，并排除其他航天器外形。"
      },
      "rubric": {
        "tier_0": "胶囊部分缺失，或画成球形、细长火箭形、机身形、平板卫星形、无宽钝底的圆柱舱段，或窄宽方向明显颠倒。",
        "tier_1": "前部具有清楚的窄顶宽底、宽端钝圆的胶囊式轮廓，未混入被排除的形态。",
        "tier_2": "在满足Pass的基础上，三分之四视角下的曲面收束、宽钝端体积和壳体分段均精确可信，透视变形不影响形态判读。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "必须能看清前部舱体从窄端到宽端的整体外轮廓；若被目标设施遮挡或裁切至无法判断，按Fail处理。"
    },
    {
      "check": "载人舱可见外壳应以白色或近白浅色为主，不应在侧壁或上部出现大面积深色涂装；宽钝底端因后段连接而不可见时，不强求显示其深色区域。",
      "lens": "K2",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "3",
          "11"
        ],
        "derivation_chain": "约束[3]规定载人舱外表面的主色及深色区域位置→题面点名串联躯干段构型，且约束[11]规定后段连接在宽钝底端→该底端在当前状态可被连接结构遮蔽，但其余可见舱体仍应保持白色或近白主色。"
      },
      "rubric": {
        "tier_0": "可见载人舱主体被画成黑色、红色、金属灰等非近白主色，或侧壁、上部出现大面积位置错误的深色区域。",
        "tier_1": "载人舱可见外壳以白色或近白浅色为主，受光与环境色变化合理，且没有错误扩张的深色涂装。",
        "tier_2": "在满足Pass的基础上，近白外壳呈现细腻的面板色差、隔热表面层次和冷蓝边缘光，同时保持准确的主色归属。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "至少需有一大片载人舱侧壁处于可辨色状态；若强烈过曝、全黑剪影或遮挡导致主色无法判断，按Fail处理。"
    },
    {
      "check": "整船应采用前部载人舱与后部躯干段沿同一纵轴串联的构型，不得缺少后段，也不得将两段并排、错轴或以侧向支架拼接。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "4",
          "11"
        ],
        "derivation_chain": "题面点名返回舱串联躯干段构型→约束[4]限定该状态属于载人舱加躯干段的串联方案→约束[11]进一步限定后段连接于载人舱宽端并保持同轴→视觉结论为两段前后同轴串接。"
      },
      "rubric": {
        "tier_0": "后部躯干段缺失，或两段并排、错轴、相互分离、连接顺序颠倒，或出现第三个不符合该构型的主要舱段。",
        "tier_1": "前部载人舱与后部躯干段前后连续、同轴连接，整体构型清晰。",
        "tier_2": "在满足Pass的基础上，两段接口圆周、中心轴线和过渡结构在透视下严密吻合，连接关系具有高精度工程可信度。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "两段主体及其连接区域均须可见；若构图裁掉后段或用阴影隐藏接口到无法判定，按Fail处理。"
    },
    {
      "check": "由于处于对接前最后接近阶段，载人舱窄端的保护结构应处于向侧方开启的状态，并使顶端连接装置清楚露出，而非仍完全封闭。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "5"
        ],
        "derivation_chain": "约束[5]规定窄端保护结构具有闭合覆盖或侧翻开启两种合法状态→题面给出即将对接的最后接近前提→对接需要暴露顶端连接装置→视觉结论为保护结构应侧翻开启并露出连接装置。"
      },
      "rubric": {
        "tier_0": "窄端没有保护结构，保护结构仍完整封闭，开启方向或铰接关系明显错误，或顶端连接装置完全未露出。",
        "tier_1": "窄端保护结构明显向侧方开启，顶端连接装置可辨认并朝向目标。",
        "tier_2": "在满足Pass的基础上，开启部件、铰接位置、内部连接装置及相互层级均刻画清楚，对接状态一目了然。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "窄端及其开启部件必须在三分之四视角中可见；若目标设施遮住窄端或细节小到无法判读，按Fail处理。"
    },
    {
      "check": "载人舱上部侧壁应出现圆形乘员舷窗，窗体应嵌入舱壁，而不是方窗、连续驾驶舱风挡或装饰性绘制圆点。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "6"
        ],
        "derivation_chain": "题面要求完整无遮挡的三分之四侧视→约束[6]规定载人舱上部侧壁设有周向分布的圆形乘员舷窗→视觉结论为当前可见侧壁至少应清楚展示圆形嵌入式舷窗。"
      },
      "rubric": {
        "tier_0": "可见上部侧壁完全没有舷窗，或舷窗被画成长方形、条带式风挡、普通飞机驾驶舱窗，或仅为无结构的涂绘圆点。",
        "tier_1": "可见上部侧壁具有至少一处清晰的圆形嵌入式乘员舷窗。",
        "tier_2": "在满足Pass的基础上，舷窗边框、玻璃凹入关系、厚度与周向布置线索精细可信，且与曲面透视严密一致。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "至少一侧上部舱壁必须清晰可见；若反光、分辨率或角度导致窗体无法辨认，按Fail处理。"
    },
    {
      "check": "龙飞船本体的轮廓不得包含固定主翼、水平尾翼或其他使其成为飞机、航天飞机式载具的翼面。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "7"
        ],
        "derivation_chain": "题面点名龙飞船并要求完整展示→约束[7]排除固定机翼和尾翼构型→视觉结论为整船外轮廓应保持无飞机式翼面的航天舱体形态。"
      },
      "rubric": {
        "tier_0": "本体出现明显固定主翼、三角翼、水平尾翼、垂直尾翼组合，或整体被画成飞机、空天飞机、航天飞机形态。",
        "tier_1": "整船没有固定主翼和尾翼，外轮廓保持无翼航天舱体构型。",
        "tier_2": "在满足Pass的基础上，主体完整剪影清晰无歧义，小型设备与结构附件也不会被误读为翼面，整体类别高度准确。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "题面要求整船完整无遮挡，因此应能检查全部主体剪影；若画外裁切使两侧轮廓不完整，按Fail处理。"
    },
    {
      "check": "龙飞船本体不得伸出大型铰接翼状太阳能阵列；能源采集表面应随躯干段外壳布设，而不是作为两侧展开的独立大翼。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "8"
        ],
        "derivation_chain": "题面点名串联躯干段构型并处于航行状态→约束[8]规定龙飞船不使用大型铰接展开太阳翼，而采用贴附躯干段表面的形式→视觉结论为不得出现独立展开的大型翼状阵列。"
      },
      "rubric": {
        "tier_0": "本体两侧或后部出现一块或多块大型铰接展开的翼状太阳能板，呈神舟飞船或空间站式展开阵列。",
        "tier_1": "本体没有大型展开太阳翼，相关表面结构保持贴合后部舱段。",
        "tier_2": "在满足Pass的基础上，完整轮廓明确排除展开翼，同时贴附式表面分区和曲面包覆关系精确、无歧义。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "整船两侧轮廓和后部舱段必须可见；若空间站局部结构与主体重叠到无法确认大型阵列归属，按Fail处理。"
    },
    {
      "check": "主体不得具有龙头、龙身、鳞片、爪、尾、须等神话龙的生物部件，也不得把工程舱体装饰成实质性的龙形生物。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "9"
        ],
        "derivation_chain": "题面中的名称可能诱发字面形象联想→约束[9]明确排除神话龙生物造型→视觉结论为主体各部分必须保持工程结构，不得转化为龙类身体部件。"
      },
      "rubric": {
        "tier_0": "主体出现龙头、龙嘴、角须、鳞片覆盖、爪肢、弯曲龙尾等任一明确生物结构，或整船轮廓被塑造成神话龙。",
        "tier_1": "主体完全保持工程航天器结构，没有任何可辨认的神话龙生物部件。",
        "tier_2": "在满足Pass的基础上，即使画面具有强烈动势和戏剧光影，所有轮廓、表面分区与附件仍保持严谨机械属性，毫无生物形态歧义。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "完整主体轮廓与主要表面均须可检查；若装饰、暗部或运动模糊造成是否存在生物部件无法判断，按Fail处理。"
    },
    {
      "check": "后部躯干段应为白色圆柱形结构，同轴接在载人舱宽端，其外表面应可见沿周向贴附布设的太阳能电池区域。",
      "lens": "K1",
      "anchor": {
        "type": "derivation",
        "constraint_refs": [
          "11"
        ],
        "derivation_chain": "题面点名返回舱串联躯干段构型→约束[11]规定该子变体的后部舱段形态、连接位置及能源表面布置→视觉结论为白色圆柱后段应同轴连接，并带有包覆外表面的贴附式太阳能电池区域。"
      },
      "rubric": {
        "tier_0": "后段缺失，或画成球形、锥形、方箱形；连接到载人舱窄端或明显偏轴；外表面完全没有贴附式太阳能电池区域，或错误改成独立展开大翼。",
        "tier_1": "后段呈白色圆柱形并同轴连接在载人舱宽端，外壳可见沿周向贴附的太阳能电池区域。",
        "tier_2": "在满足Pass的基础上，圆柱曲率、接口同轴度、白色壳体与电池区域的周向包覆透视均精确，表面分块细节完整且工程感突出。"
      },
      "variants_used": "返回舱串联躯干段构型",
      "visibility_requirement": "后部躯干段需大部分可见，且至少一段外表面足以判断圆柱形态和贴附区域；若被裁切、遮挡或处于全黑剪影中，按Fail处理。"
    }
